<template>
 <div class="app-container channel-settings"><div class="heading"><div><h2>渠道设置</h2><p>集中维护平台应用、店铺对接、商品自动同步与绑定，以及日志与提醒。</p></div><el-tag type="info">当前登录公司</el-tag></div>
 <el-tabs v-model="tab" @tab-click="changeTab"><el-tab-pane label="平台应用 · 公司级" name="apps" /><el-tab-pane label="店铺对接 · 店铺级" name="shop" /><el-tab-pane label="商品同步与绑定 · 店铺级" name="products" /><el-tab-pane label="日志与提醒" name="logs" /></el-tabs>
 <div v-if="tab!=='apps'" class="shop-bar"><span>当前店铺</span><el-select v-model="channel" filterable placeholder="选择需要设置的店铺" @change="load"><el-option v-for="s in shops" :key="s.channel_id" :value="s.channel_id" :label="s.channel_name + (s.enabled ? '' : '（已停用）')" /></el-select><el-button v-if="channel" type="text" @click="$router.push({path:'/oms-channel/platformProducts',query:{channelId:channel}})">查看平台商品</el-button><el-button v-if="channel" type="text" @click="$router.push({path:'/oms-channel/platformLogs',query:{channelId:channel}})">查看交互日志</el-button></div>
 <el-alert v-if="error" :title="error" type="error" :closable="false" />
 <div v-show="tab==='apps'||tab==='shop'" v-loading="loading"><div v-if="tab==='shop' && policy" class="panel"><h3>店铺业务开关</h3><el-form inline label-width="140px"><el-form-item label="启用平台对接"><el-switch v-model="policy.shop.to_channel_enabled" :active-value="1" :inactive-value="0" /></el-form-item><el-form-item label="库存同步总开关"><el-switch v-model="policy.shop.sync_enabled" :active-value="1" :inactive-value="0" /></el-form-item></el-form><p class="muted">库存同步总开关仅允许执行库存写入，具体 SKU、链接和分配策略在库存同步组维护。</p><el-button v-hasPermi="['channel:platform:config']" :loading="busy" type="primary" size="small" @click="saveSwitches">保存开关</el-button></div><platform-workspace ref="platform" embedded :mode="tab==='apps'?'apps':'shop'" @changed="load" @navigate="navigate" /></div>
 <template v-if="tab==='products'"><el-empty v-if="!channel" description="请先选择店铺" /><div v-else-if="policy" v-loading="loading"><div class="status"><div>最近成功同步<strong>{{ policy.last_success_at || '尚未成功同步' }}</strong></div><div>下次同步<strong>{{ policy.auto_pull ? policy.next_run_at : '自动拉取已关闭' }}</strong></div><div>当前任务<strong>{{ policy.running.length ? '任务 '+policy.running[0].id+' · '+taskState(policy.running[0].state) : '暂无执行中任务' }}</strong></div></div><el-alert v-if="policy.last_error" :title="policy.last_error" type="warning" :closable="false" /><div class="panel"><h3>自动拉取</h3><el-form label-width="190px"><el-form-item label="自动拉取平台商品"><el-switch v-model="policy.auto_pull" :active-value="1" :inactive-value="0" /></el-form-item><el-form-item label="同步周期"><el-input-number v-model="policy.interval_minutes" :min="5" :max="1440" :precision="0" /> 分钟</el-form-item></el-form><p class="muted">首次授权有效后自动拉取出售中与仓库中商品；后续按变化更新明细，并每天复核完整明细。失败任务最多自动重试3次。订单缺失商品时自动补拉。</p></div><div class="panel"><h3>自动绑定</h3><el-form label-width="190px"><el-form-item label="商家编码精确自动绑定"><el-switch v-model="policy.auto_bind" :active-value="1" :inactive-value="0" /></el-form-item><el-form-item label="未匹配商品自动重试"><el-switch v-model="policy.rematch_enabled" :active-value="1" :inactive-value="0" /></el-form-item></el-form><p class="muted">仅匹配当前公司唯一 OMS SKU。多规格使用各规格商家编码，无规格使用商品编码；未匹配商品每5分钟重新检查，可衔接新建 OMS SKU。</p><el-alert title="人工绑定、手工解绑及已忽略规格受保护；编码、规格或店铺身份变化转待核对。自动绑定不会开启平台库存同步。" type="info" :closable="false" show-icon /></div><div class="footer"><el-button v-hasPermi="['channel:platform:config']" type="primary" :loading="busy" @click="saveProducts">保存商品同步与绑定设置</el-button><el-button @click="load">刷新</el-button><el-button type="text" @click="$router.push({path:'/oms-channel/platformProducts',query:{channelId:channel,tasks:'1'}})">查看拉取任务</el-button></div></div></template>
 <template v-if="tab==='logs'"><div class="panel"><h3>日志保留期 <el-tag size="mini" type="info">公司级</el-tag></h3><el-form v-if="retention" inline><el-form-item label="摘要保留"><el-input-number v-model="retention.summary_days" :min="1" :max="3650" /> 天</el-form-item><el-form-item label="脱敏报文保留"><el-input-number v-model="retention.payload_days" :min="1" :max="retention.summary_days" /> 天</el-form-item></el-form><p class="muted">适用于当前公司的全部平台交互。到期后按定时清理任务删除，报文保留期不能超过摘要保留期。</p><el-button v-hasPermi="['channel:platform:config']" type="primary" size="small" :loading="busy" @click="saveRetention">保存日志设置</el-button></div><div class="panel"><h3>授权与服务到期提醒 <el-tag size="mini" type="info">店铺级</el-tag></h3><el-empty v-if="!channel" description="选择店铺后设置到期提醒" /><template v-else-if="reminder"><el-switch v-model="reminder.enabled" active-text="站内提醒" /><span class="gap">提前</span><el-input-number v-model="reminder.days" :min="1" :max="90" /> 天 <el-button v-hasPermi="['channel:platform:config']" :disabled="!reminder.bound" :loading="busy" size="small" @click="saveReminder">保存提醒</el-button><p class="muted">{{ reminder.bound ? '按当前店铺授权与服务订购到期时间计算。' : '该店铺尚未关联平台应用，请先完成店铺对接。' }}</p></template></div></template>
 </div>
</template>
<script>
import PlatformWorkspace from './PlatformWorkspace'
import { settingsGet,settingsPost } from '@/api/channel/settings'
import { platformGet,platformPost } from '@/api/channel/platform'
export default {name:'ChannelSettings',components:{PlatformWorkspace},data(){return{tab:'apps',channel:undefined,shops:[],policy:null,retention:null,reminder:null,loading:false,busy:false,error:'',seq:0}},
 async created(){this.tab=this.$route.query.tab||'apps';this.channel=this.$route.query.channelId?Number(this.$route.query.channelId):undefined;try{this.shops=(await settingsGet('/options')).data.shops;await this.load()}catch(_){this.error='渠道设置加载失败，请刷新重试'}},
 watch:{'$route.fullPath'(){if(this.$route.path!=='/oms-channel/settings')return;this.tab=this.$route.query.tab||'apps';this.channel=this.$route.query.channelId?Number(this.$route.query.channelId):undefined;this.load()}},beforeDestroy(){this.seq++},methods:{
 navigate(tab){this.tab=tab;this.load()},taskState(s){return {PENDING:'等待执行',RUNNING:'执行中'}[s]||s},changeTab(){this.load()},async load(){const seq=++this.seq;this.loading=true;this.error='';this.policy=null;this.reminder=null;try{if(this.tab==='apps'){await this.$nextTick();await this.$refs.platform.manage('apps')}else{if(this.tab==='logs')this.retention=(await settingsGet('/retention')).data;if(this.channel){const p=(await settingsGet('/products/'+this.channel)).data;if(seq!==this.seq)return;this.policy=p;if(this.tab==='shop'){await this.$nextTick();await this.$refs.platform.open(this.channel)}if(this.tab==='logs'){const d=(await platformGet('/shops/'+this.channel)).data;if(seq===this.seq)this.reminder={enabled:d.reminder_enabled!==0,days:d.reminder_days||7,bound:!!d.app_id}}}}}catch(_){if(seq===this.seq)this.error='设置读取失败，请刷新重试'}finally{if(seq===this.seq)this.loading=false}},
 async saveProducts(){this.busy=true;try{this.policy=(await settingsPost('/products/'+this.channel,this.policy)).data;this.$message.success('商品同步与绑定设置已保存')}finally{this.busy=false}},async saveSwitches(){this.busy=true;try{await settingsPost('/switches/'+this.channel,this.policy.shop);this.$message.success('店铺开关已保存');await this.load()}finally{this.busy=false}},async saveRetention(){this.busy=true;try{this.retention=(await settingsPost('/retention',this.retention)).data;this.$message.success('日志保留期已保存')}finally{this.busy=false}},async saveReminder(){this.busy=true;try{await platformPost('/shops/'+this.channel+'/reminder',{enabled:this.reminder.enabled,days:this.reminder.days});this.$message.success('到期提醒已保存')}finally{this.busy=false}}
}}
</script>
<style scoped>
.heading,.shop-bar,.footer{display:flex;align-items:center;justify-content:space-between;gap:16px}.heading h2{margin:0 0 8px}.heading p,.muted{color:#7c889a;font-size:13px;line-height:1.7}.shop-bar{justify-content:flex-start;padding:16px 0}.shop-bar .el-select{width:320px}.panel{padding:20px;border:1px solid #e5eaf1;border-radius:8px;margin:18px 0}.panel h3{margin:0 0 20px}.status{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;background:#f5f8fc;padding:20px}.status strong{display:block;font-size:15px;margin-top:12px}.footer{justify-content:flex-start;margin:20px 0}.gap{margin:0 16px}
</style>
